/// The spoken form of a bank entry, and why it differs. `None` means the entry
/// is not in the bank -- callers must treat that as a build-time bug, never as
/// "no sandhi".
pub fn lookup(entry: &str) -> Option<(&'static str, &'static str)> {
    SANDHI
        .binary_search_by(|(k, _, _)| (*k).cmp(entry))
        .ok()
        .map(|i| (SANDHI[i].1, SANDHI[i].2))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pinyin::{grade_sandhi_aware, tier_accepts_surface, ToneMode};

    #[test]
    fn every_bank_entry_has_a_row() {
        // Invariant 3: a missing field is a build failure, not a fallback. A
        // word with no surface form is a word TTS cannot speak.
        let mut missing = Vec::new();
        for tier in ["easy", "medium", "hard", "expert"] {
            for entry in crate::words::tier_for("zh", tier) {
                if lookup(entry).is_none() {
                    missing.push(*entry);
                }
            }
        }
        assert!(missing.is_empty(), "{} entries lack sandhi: {:?}", missing.len(), &missing[..missing.len().min(5)]);
    }

    #[test]
    fn the_table_is_sorted_for_binary_search() {
        let mut keys: Vec<&str> = SANDHI.iter().map(|(k, _, _)| *k).collect();
        let orig = keys.clone();
        keys.sort_unstable();
        assert_eq!(keys, orig, "generated table must ship sorted");
    }

    #[test]
    fn a_class_of_none_never_moves_a_tone() {
        for (entry, surface, class) in SANDHI {
            let citation = entry.split('|').next().unwrap_or(entry);
            if class == "none" {
                assert_eq!(surface, citation, "{entry}: 'none' but the tone moved");
            } else {
                assert_ne!(surface, citation, "{entry}: '{class}' but nothing moved");
            }
        }
    }

    // ---- D4: the tier split ----

    #[test]
    fn tiers_one_and_two_accept_what_the_player_heard() {
        // ni3hao3 is SPOKEN ni2hao3. At tiers 1-2 both are correct, and the
        // caller is told which, because the surface pass owes a teaching note.
        let (v, via) = grade_sandhi_aware(
            "ni2hao3", "ni3hao3", Some("ni2hao3"), ToneMode::Graded, true);
        assert!(v.is_correct());
        assert!(via, "a surface match must announce itself");

        let (v, via) = grade_sandhi_aware(
            "ni3hao3", "ni3hao3", Some("ni2hao3"), ToneMode::Graded, true);
        assert!(v.is_correct());
        assert!(!via, "the citation is not a surface match");
    }

    #[test]
    fn tier_three_and_up_take_the_citation_only() {
        let (v, via) = grade_sandhi_aware(
            "ni2hao3", "ni3hao3", Some("ni2hao3"), ToneMode::Graded, false);
        assert!(!v.is_correct(), "tier 3+ does not accept the spoken form");
        assert!(!via);
        // ...and it reads as a TONE miss, not a spelling one: the player had
        // every syllable right.
        assert!(v.is_tone_only(), "surface input at tier 3+ is a tone miss");
    }

    #[test]
    fn the_tier_split_is_where_d4_says() {
        assert!(tier_accepts_surface("easy"));
        assert!(tier_accepts_surface("medium"));
        assert!(!tier_accepts_surface("hard"));
        assert!(!tier_accepts_surface("expert"));
    }

    #[test]
    fn a_word_without_sandhi_gains_nothing_from_the_lenient_tiers() {
        // Where surface == citation there is no second chance to give.
        let (v, via) = grade_sandhi_aware(
            "ma1", "ma3", Some("ma3"), ToneMode::Graded, true);
        assert!(!v.is_correct());
        assert!(!via);
    }

    #[test]
    fn a_wrong_answer_keeps_its_citation_verdict() {
        // A surface miss is not a more useful description of the same mistake,
        // so the verdict the player sees is the one against the citation.
        let (v, via) = grade_sandhi_aware(
            "ni2hao1", "ni3hao3", Some("ni2hao3"), ToneMode::Graded, true);
        assert!(!v.is_correct());
        assert!(!via);
    }
}
